#include "omnipresent_mesh.h"
int mesh_compute(const LayerBudget* layers,int n,MeshResult* out){if(!layers||!out||n<=0)return -1;double h=0,r=0;int grid=0;for(int i=0;i<n;i++){const LayerBudget*L=&layers[i];if(L->node_count<0)return -2;if(L->harvested_w_per_node<0)return -3;if(L->idle_w_per_node<0)return -4;if(L->workload_w_per_node<0)return -5;double lh=L->harvested_w_per_node*L->node_count,lr=(L->idle_w_per_node+L->workload_w_per_node)*L->node_count;h+=lh;r+=lr;if(lh<lr)grid=1;}out->total_harvested_w=h;out->total_required_w=r;out->coverage_ratio=r>0?h/r:0;out->self_running=(r>0&&h>=r);out->any_layer_needs_grid=grid;return 0;}
int mesh_emit_receipt(const MeshResult*r,ibare_u8 out[32]){if(!r||!out)return -1;ibare_u8 b[36];const double f[4]={r->total_harvested_w,r->total_required_w,r->coverage_ratio,(double)r->self_running};for(int i=0;i<4;i++){const ibare_u8*p=(const ibare_u8*)&f[i];for(int j=0;j<8;j++)b[i*8+j]=p[j];}b[32]=(ibare_u8)(r->any_layer_needs_grid?1:0);b[33]=b[34]=b[35]=0;IBARE_SHA256_CTX c;ibare_sha256_init(&c);ibare_sha256_update(&c,b,sizeof b);ibare_sha256_final(&c,out);return 0;}
